import fs from 'node:fs/promises';
import path from 'node:path';
import { escapeHtml as e } from './core.mjs';
export async function writeReport(output, report) {
  await fs.mkdir(output, { recursive: true });
  const counts = Object.fromEntries(['changed', 'unchanged', 'added', 'removed', 'error'].map(status => [status, report.pages.filter(p => p.status === status).length]));
  report.counts = counts;
  await fs.writeFile(path.join(output, 'summary.json'), JSON.stringify(report, null, 2) + '\n');
  const priority = { error: 0, changed: 1, added: 2, removed: 3, unchanged: 4 };
  const cards = [...report.pages].sort((a, b) => priority[a.status] - priority[b.status] || a.route.localeCompare(b.route)).map(item => {
    const images = ['base', 'head', 'diff'].filter(key => item[key]).map(key => `<figure><figcaption>${key === 'base' ? 'Before' : key === 'head' ? 'After' : 'Difference'}</figcaption><a href="${e(item[key])}"><img loading="lazy" src="${e(item[key])}" alt="${e(key + ' ' + item.route)}"></a></figure>`).join('');
    return `<details ${item.status === 'unchanged' ? '' : 'open'}><summary><strong>${e(item.route)}</strong> · ${e(item.profile)} ${e(item.state)} · ${e(item.status)}${item.diffPixels === undefined ? '' : ` · ${item.diffPixels} changed pixels (${(item.diffRatio * 100).toFixed(3)}%)`}${item.sizeChanged ? ' · page dimensions changed' : ''}</summary>${(item.errors || []).map(error => `<p class="error">${e(error)}</p>`).join('')}<div class="images">${images}</div></details>`;
  }).join('\n');
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Documentation visual comparison</title><style>body{font:16px system-ui,sans-serif;margin:2rem;color:#182337;background:#f5f7fa}h1{font-size:1.8rem}code{overflow-wrap:anywhere}details{background:white;padding:1rem;margin:1rem 0;border:1px solid #ccd4dd;border-radius:8px}summary{cursor:pointer;overflow-wrap:anywhere}.images{display:flex;align-items:flex-start;gap:1rem;margin-top:1rem}figure{flex:1;min-width:0;margin:0}img{width:100%;height:auto;border:1px solid #dde2e8}figcaption{font-weight:600;margin-bottom:.5rem}.error{color:#a11919;white-space:pre-wrap}.note{padding:1rem;background:#e4edf7}a{color:#154e97}@media(max-width:700px){body{margin:.7rem}.images{display:block}figure{margin-bottom:1rem}}</style></head><body><h1>Documentation visual comparison</h1>${report.status === 'incomplete' ? '<p class="error">INCOMPLETE: this run has not finished. Do not treat partial captures as full coverage.</p>' : ''}<p>Before: <code>${e(report.baseSha || 'unresolved')}</code><br>After: <code>${e(report.headSha || 'unresolved')}</code></p><p>${e(report.generatedAt)} · ${e(report.color || 'light')} · ${e(report.scope || 'all rendered routes')}</p><p class="note">Report-only review aid. Visual changes are expected, not test failures. Counts are captures (route × viewport/state), not unique pages. Both sides were captured together; no committed golden images. Click an image to inspect it at full size.</p><p>${Object.entries(counts).map(([key, count]) => `${count} ${key}`).join(' · ')}</p>${(report.errors || []).map(error => `<p class="error">${e(error)}</p>`).join('')}${report.externalAssets?.length ? `<p>${report.externalAssets.length} external images/fonts cached for this run from the documented allowed asset origins. Other external requests were blocked.</p>` : ''}${cards || '<p>No screenshots were produced. See errors and build logs.</p>'}<p>Keep this whole folder together. The report uses only local images and contains no executable page content. GitHub artifacts require sign-in/read access and expire after the workflow retention period.</p></body></html>`;
  await fs.writeFile(path.join(output, 'index.html'), html);
}
